import numpy as np

def se2(x, y, theta):
    c, s = np.cos(theta), np.sin(theta)
    return np.array([[c, -s, x], [s, c, y], [0, 0, 1.0]])

def scan_to_world(W_T_B, B_T_L, ranges, bearings):
    ranges = np.asarray(ranges, dtype=float)
    bearings = np.asarray(bearings, dtype=float)
    pts_L = np.stack([ranges * np.cos(bearings), ranges * np.sin(bearings), np.ones_like(ranges)])
    pts_W = W_T_B @ B_T_L @ pts_L
    return pts_W[:2].T

