import numpy as np

def se2(x, y, theta):
    c, s = np.cos(theta), np.sin(theta)
    return np.array([[c, -s, x], [s, c, y], [0, 0, 1.0]])

def relative_pose(W_T_A, W_T_B):
    R, t = W_T_A[:2, :2], W_T_A[:2, 2]
    A_T_W = np.eye(3)
    A_T_W[:2, :2], A_T_W[:2, 2] = R.T, -R.T @ t
    A_T_B = A_T_W @ W_T_B
    x, y = A_T_B[0, 2], A_T_B[1, 2]
    theta = np.arctan2(A_T_B[1, 0], A_T_B[0, 0])
    return float(x), float(y), float(theta)
